-- Carta de demostración "Café del Pintor" (Calle Urriola 652, Cerro Alegre, Valparaíso), para mostrársela al restaurante.
-- Hecha con su carta real (PDF de su Linktree, 10 páginas): menú del día $15.990, platos, bebidas, vinos y coctelería,
-- con sus precios exactos. Nombres de platos en español; descripciones traducidas a inglés, portugués, francés, alemán, italiano, chino y holandés.
-- Los 3 platos con hoja verde en el PDF van con la etiqueta "vegetariano". Logo: public/demo/cafe-del-pintor/logo.png.
-- Los horarios de reserva (almuerzo 13:00-15:30, cena 19:00-21:30) son de referencia: el PDF no los trae.
-- Se puede ejecutar más de una vez: borra y vuelve a crear la carta de la demo (categorías y platos), sin tocar nada más.

do $$
declare
  rid uuid;
  cid uuid;
begin
  select id into rid from public.restaurantes where slug = 'cafe-del-pintor';
  if rid is null then
  end if;
  update public.restaurantes set
    nombre = 'Café del Pintor',
    descripcion = 'Cocina chilena con un toque único y murales que cuentan historias · Calle Urriola 652, Cerro Alegre, Valparaíso',
    logo_url = '/demo/cafe-del-pintor/logo.png',
    tema = 'revista',
    color_primario = '#4d6a46',
    color_fondo = '#eee8e1',
    moneda = 'CLP',
    plan = 'pro',
    idiomas = array['en', 'pt', 'fr', 'de', 'it', 'zh', 'nl'],
    traducciones = '{"en": {"descripcion": "Chilean cuisine with a unique twist and murals that tell stories · Calle Urriola 652, Cerro Alegre, Valparaíso"}, "pt": {"descripcion": "Cozinha chilena com um toque único e murais que contam histórias · Calle Urriola 652, Cerro Alegre, Valparaíso"}, "fr": {"descripcion": "Cuisine chilienne avec une touche unique et des fresques qui racontent des histoires · Calle Urriola 652, Cerro Alegre, Valparaíso"}, "de": {"descripcion": "Chilenische Küche mit besonderer Note und Wandbilder, die Geschichten erzählen · Calle Urriola 652, Cerro Alegre, Valparaíso"}, "it": {"descripcion": "Cucina cilena con un tocco unico e murales che raccontano storie · Calle Urriola 652, Cerro Alegre, Valparaíso"}, "zh": {"descripcion": "独具特色的智利美食与讲述故事的壁画 · Calle Urriola 652, Cerro Alegre, 瓦尔帕莱索"}, "nl": {"descripcion": "Chileense keuken met een unieke twist en muurschilderingen die verhalen vertellen · Calle Urriola 652, Cerro Alegre, Valparaíso"}}'::jsonb,
    ajustes = ajustes || '{"pais": "CL", "zona_horaria": "America/Santiago", "imagenes_defecto": true, "sonido_hoja": "papel", "redes": {"instagram": "https://www.instagram.com/cafedelpintor/"}, "estaciones": ["Cocina", "Barra"], "modulos": {"reservas": true}, "reservas": {"online": true, "tolerancia": 15, "mostrar_tolerancia": true, "recordatorio": true, "horas_antes": 3, "ninos": true, "correo": "opcional", "turnos": [{"nombre": "Almuerzo", "desde": "13:00", "hasta": "15:30", "cada": 30, "dias": [], "cupo": 0}, {"nombre": "Cena", "desde": "19:00", "hasta": "21:30", "cada": 30, "dias": [], "cupo": 0}]}}'::jsonb
  where id = rid;

  delete from public.platos where restaurante_id = rid;
  delete from public.categorias where restaurante_id = rid;
end $$;
